func deconv(g: [Double], f: [Double]) -> [Double] {
  let fs = f.count
  var ret = [Double](repeating: 0, count: g.count - fs + 1)

  for n in 0..<ret.count {
    ret[n] = g[n]
    let lower = n >= fs ? n - fs + 1 : 0

    for i in lower..<n {
      ret[n] -= ret[i] * f[n - i]
    }

    ret[n] /= f[0]
  }

  return ret
}

func perfectShuffle<T>(_ arr: [T]) -> [T]? {
  guard arr.count & 1 == 0 else {
    return nil
  }

  let half = arr.count / 2
  var res = [T]()

  for i in 0..<half {
    res.append(arr[i])
    res.append(arr[i + half])
  }

  return res
}

func angleDifference(a1: Double, a2: Double) -> Double {
  let diff = (a2 - a1).truncatingRemainder(dividingBy: 360)

  if diff < -180.0 {
    return 360.0 + diff
  } else if diff > 180.0 {
    return -360.0 + diff
  } else {
    return diff
  }
}

func levenshteinDistance(string1: String, string2: String) -> Int {
    let m = string1.count
    let n = string2.count
    if m == 0 {
        return n
    }
    if n == 0 {
        return m
    }
    var costs = Array(0...n)
    for (i, c1) in string1.enumerated() {
        costs[0] = i + 1
        var corner = i
        for (j, c2) in string2.enumerated() {
            let upper = costs[j + 1]
            if c1 == c2 {
                costs[j + 1] = corner
            } else {
                costs[j + 1] = 1 + min(costs[j], upper, corner)
            }
            corner = upper
        }
    }
    return costs[n]
}

