public func chowla<T: BinaryInteger>(n: T) -> T {
  stride(from: 2, to: T(Double(n).squareRoot()+1), by: 1)
    .lazy
    .filter({ n % $0 == 0 })
    .reduce(0, {(s: T, m: T) in
      m*m == n ? s + m : s + m + (n / m)
    })
}

extension BinaryInteger {
  @inlinable
  public var isZumkeller: Bool {
    let divs = factors(sorted: false)
    let sum = divs.reduce(0, +)
    guard sum & 1 != 1 else {
      return false
    }
    guard self & 1 != 1 else {
      let abundance = sum - 2*self
      return abundance > 0 && abundance & 1 == 0
    }
    return isPartSum(divs: divs[...], sum: sum / 2)
  }
  @inlinable
}
