private func isKPrime() -> Bool {
  var primes = 0
  var f = 2
  var rem = n

  while primes < k && rem > 1 {
    while rem % f == 0 && rem > 1 {
      rem /= f
      primes += 1
    }

    f += 1
  }

  return rem == 1 && primes == k
}

